-- Slice 1: locations and products.
-- IDs are time-ordered UUIDv7 generated by Postgres (requires PostgreSQL 18+).

create table location (
    id          uuid        primary key default uuidv7(),
    name        text        not null check (char_length(btrim(name)) between 1 and 60),
    sort_order  integer     not null check (sort_order >= 0),
    created_at  timestamptz not null default now(),
    updated_at  timestamptz not null default now()
);

create unique index location_name_uq on location (lower(name));

create table product (
    id                  uuid          primary key default uuidv7(),
    name                text          not null check (char_length(btrim(name)) between 1 and 100),
    category            text          check (char_length(category) <= 50),
    tracking_mode       text          not null check (tracking_mode in ('COUNTED', 'STATUS')),
    default_unit        text          check (default_unit in ('piece', 'g', 'kg', 'ml', 'l', 'pack', 'tin')),
    default_location_id uuid          references location (id) on delete set null,
    min_quantity        numeric(10, 3) check (min_quantity >= 0),
    barcode             text          check (char_length(barcode) between 1 and 64),
    created_at          timestamptz   not null default now(),
    updated_at          timestamptz   not null default now(),
    -- default_unit and min_quantity only make sense for COUNTED products
    constraint product_counted_only_fields check (
        tracking_mode = 'COUNTED' or (default_unit is null and min_quantity is null)
    )
);

create unique index product_name_uq on product (lower(name));
create unique index product_barcode_uq on product (barcode) where barcode is not null;
create index product_default_location_idx on product (default_location_id);
